mapper.select:
select
,s.shopNum
from merchant_fee_model mt
LEFT JOIN (SELECT merchant_fee_model_id,count(1) as shopNum from shop WHERE deleted = 0 GROUP BY
merchant_fee_model_id) s
on mt.id = s.merchant_fee_model_id

    and mt.id = #{id}
    and mt.name like concat('%', #{name}, '%')
    and mt.process_fee_eu_usd = #{processFeeEuUsd}
    and mt.process_fee_eu_non_usd = #{processFeeEuNonUsd}
    and mt.process_fee_non_eu_usd = #{processFeeNonEuUsd}
    and mt.process_fee_non_eu_non_usd = #{processFeeNonEuNonUsd}
    and mt.gateway_fee_threshold = #{gatewayFeeThreshold}
    and mt.gateway_fee_below_threshold =
        #{gatewayFeeBelowThreshold}

    and mt.gateway_fee_above_threshold =
        #{gatewayFeeAboveThreshold}

    and mt.rolling_reserve_rate = #{rollingReserveRate}
    and mt.rolling_reserve_release_days =
        #{rollingReserveReleaseDays}

    and mt.exchange_rate_bps = #{exchangeRateBps}
    and mt.refund_fee = #{refundFee}
    and mt.rdr_fee = #{rdrFee}
    and mt.cb_fee = #{cbFee}
    and mt.created_by = #{createdBy}
    and mt.created_at = #{createdAt}
    and mt.update_by = #{updateBy}
    and mt.update_at = #{updateAt}
    and mt.deleted_at = #{deletedAt}
    and mt.deleted = #{deleted}
    and mt.deleted = 0

order by mt.id desc
